def aplicar_clareza(apps, schema_editor):
    """Troca para a identidade Clareza só quem ainda usa as cores padrão antigas."""
    CompanyProfile = apps.get_model("core", "CompanyProfile")
    for perfil in CompanyProfile.objects.all():
        atuais = {perfil.primary_color.upper(), perfil.sidebar_color.upper(), perfil.accent_color.upper()}
        if atuais == ANTIGAS:
            perfil.primary_color = "#0B7A83"
            perfil.sidebar_color = "#0D3B45"
            perfil.accent_color = "#F08A4B"
            perfil.save(update_fields=["primary_color", "sidebar_color", "accent_color"])


